import{_ as t,o,c as r,a5 as s}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Sequence Flow — Remove Member","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-9-remove-member/sequence-flow.md","filePath":"feature/agency-workspace/3-4-9-remove-member/sequence-flow.md"}'),a={name:"feature/agency-workspace/3-4-9-remove-member/sequence-flow.md"};function n(i,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="sequence-flow-—-remove-member" tabindex="-1">Sequence Flow — Remove Member <a class="header-anchor" href="#sequence-flow-—-remove-member" aria-label="Permalink to &quot;Sequence Flow — Remove Member&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.9). This file lists each actor → action → system step in enough detail to draw the sequence diagram directly. Business explanation lives in <code>spec.md</code>. &gt; &gt; Updated 2026-09-23, matching the system as built today.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Owner</strong></li><li><strong>Client</strong> — the BrandHub web application.</li><li><strong>System</strong> — the BrandHub service.</li><li><strong>Database</strong> — PostgreSQL (<code>agency_members</code>).</li></ul><hr><h2 id="flow-a-—-a-member-is-removed-successfully" tabindex="-1">Flow A — A member is removed successfully <a class="header-anchor" href="#flow-a-—-a-member-is-removed-successfully" aria-label="Permalink to &quot;Flow A — A member is removed successfully&quot;">​</a></h2><ol><li>Owner → Client: opens the Member list of the Agency, selects Remove on a member row other than their own, and confirms.</li><li>Client → System: submits the removal with the member record identifier (<code>DELETE /api/v1/agencies/{agencyId}/members/{memberId}</code>). The identifier is the member record of the Agency, not the person&#39;s user identifier.</li><li>System — remove: a. Loads the Agency by its identifier — not found → <code>404 AGENCY_NOT_FOUND</code>. b. Confirms the caller is the Owner of the Agency — otherwise <code>403 NOT_AGENCY_OWNER</code>. c. Finds the member record by identifier inside that Agency — not found → <code>404 NOT_FOUND</code>. d. Confirms the record is not the Owner&#39;s own — if it is → <code>409 CANNOT_REMOVE_OWNER</code>. e. Removes the member record.</li><li>System → Client: no data, the removal is done.</li><li>Client: drops the row and shows a confirmation. The person loses access to the Agency and to every one of its Workspaces immediately, because access everywhere rests on the member record that has just been removed.</li><li>The resources that person created — tasks, materials, content and the like — are neither removed nor reassigned. They stay with the Workspace and the Agency.</li></ol><h2 id="flow-b-—-the-owner-s-own-record-is-targeted-refused" tabindex="-1">Flow B — The Owner&#39;s own record is targeted (refused) <a class="header-anchor" href="#flow-b-—-the-owner-s-own-record-is-targeted-refused" aria-label="Permalink to &quot;Flow B — The Owner&#39;s own record is targeted (refused)&quot;">​</a></h2><ol><li>Owner → Client: selects Remove on the Owner row, when the Client does not hide that action, or submits the removal directly with the Owner&#39;s member record identifier.</li><li>Client → System: submits the removal (<code>DELETE /api/v1/agencies/{agencyId}/members/{memberId}</code>).</li><li>System: runs steps 3.a to 3.c of Flow A as usual, then reaches 3.d — the record is the Owner&#39;s own, so the removal is refused with <code>409 CANNOT_REMOVE_OWNER</code>.</li><li>System → Client: the refusal, <code>409 CANNOT_REMOVE_OWNER</code>.</li><li>Client: shows the failure and removes nothing.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>Error code</th></tr></thead><tbody><tr><td>Remove</td><td>Caller is not the Owner of the Agency</td><td>403</td><td><code>NOT_AGENCY_OWNER</code></td></tr><tr><td>Remove</td><td>The member record does not exist or belongs to another Agency</td><td>404</td><td><code>NOT_FOUND</code></td></tr><tr><td>Remove</td><td>The member record is the Owner&#39;s own</td><td>409</td><td><code>CANNOT_REMOVE_OWNER</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Correction applied:</strong> an earlier revision recorded the attempt to remove the Owner as refused with <code>403 FORBIDDEN</code>. The system now answers with its own code, <code>CANNOT_REMOVE_OWNER</code> at <code>409</code>, meaning the request conflicts with the state of the Agency rather than being forbidden outright. The correction is closed.</li></ul>',14)])])}const w=t(a,[["render",n]]);export{u as __pageData,w as default};
